// Supabase Edge Function: budget-drafts
//
// Crea un Draft de Gmail (borrador, NO se envía) por cada proveedor recibido,
// usando la cuenta de Gmail elegida por el admin ("Enviado por"), autorizada vía OAuth.
//
// Deploy: guardar este archivo en /volumes/functions/budget-drafts/index.ts en el VPS
// (mismo mount point que /volumes/functions/hello/index.ts) y reiniciar/redeploy el
// contenedor supabase-edge-functions.
//
// Variables de entorno necesarias (Environment del servicio Supabase en Dokploy):
//   GOOGLE_CLIENT_ID
//   GOOGLE_CLIENT_SECRET
//   GOOGLE_REFRESH_TOKEN_SOFIA       (refresh token de sofia@sfeventsboutique.com)
//   GOOGLE_REFRESH_TOKEN_GUADALUPE   (refresh token de guadalupe.alberti@sfeventsboutique.com)
//   GOOGLE_REFRESH_TOKEN_LUZ         (refresh token de luz.adaro@sfeventsboutique.com)
// Cada cuenta se obtiene una única vez con get-google-refresh-token.html (ver GUIA_GMAIL_SETUP.md).
// Client ID/Secret son compartidos entre cuentas (mismo proyecto de Google Cloud); el refresh
// token es específico de cada casilla.
//
// Request body esperado (JSON):
// {
//   "senderKey": "sofia" | "guadalupe" | "luz",
//   "subject": "...",
//   "body": "...",
//   "providers": [ { "id": "...", "emails": ["a@x.com", "b@x.com"] }, ... ]
// }
//
// Response:
// { "results": [ { "providerId": "...", "success": true, "draftId": "..." }, ... ] }

import { serve } from 'https://deno.land/std@0.177.1/http/server.ts'

const CORS_HEADERS = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
}

const GOOGLE_CLIENT_ID = Deno.env.get('GOOGLE_CLIENT_ID')!
const GOOGLE_CLIENT_SECRET = Deno.env.get('GOOGLE_CLIENT_SECRET')!

// Un refresh token por casilla de correo. Agregar acá cuando se conecte una cuenta nueva.
const SENDER_REFRESH_TOKENS: Record<string, string | undefined> = {
  sofia: Deno.env.get('GOOGLE_REFRESH_TOKEN_SOFIA'),
  guadalupe: Deno.env.get('GOOGLE_REFRESH_TOKEN_GUADALUPE'),
  luz: Deno.env.get('GOOGLE_REFRESH_TOKEN_LUZ'),
}

// Firma de cada casilla: imagen (PNG/JPEG) "horneada" en base64 directo en el código,
// porque Deno no tiene disco persistente en producción. Se adjunta inline (Content-ID)
// al pie del mail. Si el diseño de una firma cambia, hay que regenerar este bloque.
const SENDER_SIGNATURES: Record<string, { mime: string; base64: string } | undefined> = {
  sofia: { mime: 'image/png', base64: '' },
  guadalupe: { mime: 'image/jpeg', base64: '' },
  luz: { mime: 'image/png', base64: '' },
}

// Intercambia el refresh token de la cuenta elegida por un access token de corta duración.
// Se hace en cada invocación (no hay estado persistente en Edge Functions);
// el costo es una sola llamada HTTP extra por lote de proveedores.
async function getAccessToken(senderKey: string): Promise<string> {
  const refreshToken = SENDER_REFRESH_TOKENS[senderKey]
  if (!refreshToken) {
    throw new Error(`Esta cuenta aún no está conectada (falta configurar GOOGLE_REFRESH_TOKEN_${senderKey.toUpperCase()}).`)
  }

  const res = await fetch('https://oauth2.googleapis.com/token', {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams({
      client_id: GOOGLE_CLIENT_ID,
      client_secret: GOOGLE_CLIENT_SECRET,
      refresh_token: refreshToken,
      grant_type: 'refresh_token',
    }),
  })

  if (!res.ok) {
    const text = await res.text()
    throw new Error(`No se pudo renovar el token de Google: ${res.status} ${text}`)
  }

  const data = await res.json()
  return data.access_token as string
}

// Convierte un string UTF-16 (el formato interno de JS) a bytes UTF-8 representados
// como un string "binario" (un char = un byte), el formato que espera btoa().
// Sin este paso, btoa() trata cada caracter como si fuera latin1 y rompe tildes/ñ.
function utf8Binary(str: string): string {
  const bytes = new TextEncoder().encode(str)
  let binary = ''
  for (const byte of bytes) binary += String.fromCharCode(byte)
  return binary
}

function toBase64(str: string): string {
  return btoa(utf8Binary(str))
}

// Escapa caracteres HTML básicos para que el texto del template no rompa el markup
// si en algún momento incluye < > & (defensivo; hoy los templates no los usan).
function escapeHtml(str: string): string {
  return str
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
}

// Convierte el body en texto plano (párrafos separados por líneas en blanco) a HTML,
// preservando los saltos de línea simples dentro de un mismo párrafo. Esto evita el
// "wrap corto" que se ve en algunos clientes/exportaciones a PDF con text/plain: al
// renderizar como HTML con párrafos normales, el texto fluye a todo el ancho disponible.
function bodyToHtml(body: string): string {
  const paragraphs = body.split(/\n\s*\n/).map(p => p.trim()).filter(Boolean)
  return paragraphs
    .map(p => `<p style="margin:0 0 16px 0;">${escapeHtml(p).replace(/\n/g, '<br>')}</p>`)
    .join('\n')
}

// Arma el HTML completo del cuerpo del mail, incluyendo la firma embebida (si la casilla
// tiene una configurada) referenciada por Content-ID (cid:signature).
function buildHtmlBody(body: string, hasSignature: boolean): string {
  const bodyHtml = bodyToHtml(body)
  const signatureHtml = hasSignature
    ? '<div style="margin-top:24px;"><img src="cid:signature" alt="Firma" style="max-width:320px; width:100%; height:auto; display:block;"></div>'
    : ''
  return `<!DOCTYPE html><html><body style="font-family:Arial,Helvetica,sans-serif; font-size:14px; color:#1a1a1a; line-height:1.5;">
${bodyHtml}
${signatureHtml}
</body></html>`
}

// Codifica un mensaje de email en el formato base64url que espera la Gmail API.
// El mensaje es multipart/related: una parte text/html (el cuerpo) + una parte
// image/* inline (la firma, referenciada por cid: desde el HTML). Si la casilla no
// tiene firma configurada, se arma como un mensaje HTML simple (sin multipart).
function buildRawMessage(to: string[], subject: string, htmlBody: string, signature?: { mime: string; base64: string }): string {
  const subjectHeader = `Subject: =?UTF-8?B?${toBase64(subject)}?=`

  if (!signature) {
    const headers = [
      `To: ${to.join(', ')}`,
      subjectHeader,
      'Content-Type: text/html; charset="UTF-8"',
      'MIME-Version: 1.0',
    ].join('\r\n')
    const message = `${headers}\r\n\r\n${htmlBody}`
    return toBase64(message).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '')
  }

  const boundary = `----=_Part_${crypto.randomUUID()}`
  const headers = [
    `To: ${to.join(', ')}`,
    subjectHeader,
    'MIME-Version: 1.0',
    `Content-Type: multipart/related; boundary="${boundary}"`,
  ].join('\r\n')

  const htmlPart = [
    `--${boundary}`,
    'Content-Type: text/html; charset="UTF-8"',
    'Content-Transfer-Encoding: base64',
    '',
    toBase64(htmlBody).replace(/(.{76})/g, '$1\r\n'),
  ].join('\r\n')

  const imagePart = [
    `--${boundary}`,
    `Content-Type: ${signature.mime}`,
    'Content-Transfer-Encoding: base64',
    'Content-ID: <signature>',
    'Content-Disposition: inline; filename="firma.png"',
    '',
    signature.base64.replace(/(.{76})/g, '$1\r\n'),
  ].join('\r\n')

  const message = `${headers}\r\n\r\n${htmlPart}\r\n${imagePart}\r\n--${boundary}--\r\n`

  return toBase64(message).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '')
}

async function createGmailDraft(accessToken: string, to: string[], subject: string, body: string, signature?: { mime: string; base64: string }): Promise<string> {
  const htmlBody = buildHtmlBody(body, !!signature)
  const raw = buildRawMessage(to, subject, htmlBody, signature)

  const res = await fetch('https://gmail.googleapis.com/gmail/v1/users/me/drafts', {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${accessToken}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ message: { raw } }),
  })

  if (!res.ok) {
    const text = await res.text()
    throw new Error(`Gmail API error ${res.status}: ${text}`)
  }

  const data = await res.json()
  return data.id as string
}

serve(async (req: Request) => {
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: CORS_HEADERS })
  }

  if (req.method !== 'POST') {
    return new Response(JSON.stringify({ error: 'Method not allowed' }), {
      status: 405,
      headers: { ...CORS_HEADERS, 'Content-Type': 'application/json' },
    })
  }

  try {
    const { senderKey, subject, body, providers, debug } = await req.json()

    // Modo diagnóstico: devuelve el mensaje MIME crudo (decodificado) sin llamar a Gmail,
    // para poder inspeccionar el armado del multipart/related sin depender de cómo lo
    // renderiza el compositor de Gmail. Se activa pasando "debug": true en el body.
    if (debug) {
      const signature = SENDER_SIGNATURES[senderKey]
      const htmlBody = buildHtmlBody(body || 'debug', !!signature)
      const rawUrlSafe = buildRawMessage(['debug@example.com'], subject || 'debug', htmlBody, signature)
      const rawStandard = rawUrlSafe.replace(/-/g, '+').replace(/_/g, '/')
      const decoded = new TextDecoder().decode(
        Uint8Array.from(atob(rawStandard), c => c.charCodeAt(0))
      )
      return new Response(JSON.stringify({ hasSignature: !!signature, mimeLength: decoded.length, mime: decoded }), {
        status: 200,
        headers: { ...CORS_HEADERS, 'Content-Type': 'application/json' },
      })
    }

    if (!senderKey || !subject || !body || !Array.isArray(providers) || providers.length === 0) {
      return new Response(JSON.stringify({ error: 'Faltan senderKey, subject, body o providers' }), {
        status: 400,
        headers: { ...CORS_HEADERS, 'Content-Type': 'application/json' },
      })
    }

    if (!(senderKey in SENDER_REFRESH_TOKENS)) {
      return new Response(JSON.stringify({ error: `Remitente desconocido: ${senderKey}` }), {
        status: 400,
        headers: { ...CORS_HEADERS, 'Content-Type': 'application/json' },
      })
    }

    const accessToken = await getAccessToken(senderKey)
    const signature = SENDER_SIGNATURES[senderKey]

    const results = []
    for (const provider of providers) {
      const emails: string[] = provider.emails || []
      if (emails.length === 0) {
        results.push({ providerId: provider.id, success: false, error: 'Proveedor sin email' })
        continue
      }
      try {
        const draftId = await createGmailDraft(accessToken, emails, subject, body, signature)
        results.push({ providerId: provider.id, success: true, draftId })
      } catch (e) {
        results.push({ providerId: provider.id, success: false, error: String(e?.message || e) })
      }
    }

    return new Response(JSON.stringify({ results }), {
      status: 200,
      headers: { ...CORS_HEADERS, 'Content-Type': 'application/json' },
    })
  } catch (e) {
    return new Response(JSON.stringify({ error: String(e?.message || e) }), {
      status: 500,
      headers: { ...CORS_HEADERS, 'Content-Type': 'application/json' },
    })
  }
})
